// Finite state machine to synchronously receive a 8-bit data byte,
// prepended by a start bit and followed by a stop bit. The FSM
// transitions between states to wait for start, data, and stop bits,
// and captures the data byte when a stop bit is found. The done
// signal is asserted high each time a stop bit is found, to indicate
// that a byte has been correctly received. The out_byte register
// outputs the correctly-received byte.
module TopModule (
    input  clk,
    input  in,
    input  reset,
    output reg [7:0] out_byte,
    output reg done
);
    reg [2:0] state;
    reg [7:0] data_byte;
    integer i;
    always @(posedge clk) begin
        if (reset) begin
            state <= 0;
            done <= 0;
        end else begin
            case (state)
                0: begin // wait for start bit
                    if (!in) begin
                        state <= 1;
                        data_byte <= 0;
                    end
                end
                1: begin // collect data bits 0-7
                    data_byte <= {in, data_byte[7:1]};
                    if (&state) state <= 2;
                    else state <= state + 1;
                end
                2: begin // wait for stop bit
                    if (in) done <= 1;
                    out_byte <= data_byte;
                    state <= 0;
                end
            endcase
        end
    end
endmodule

