// Finite state machine to decode 8-bit bytes from a stream of bits, with start
// and stop bits, as described in the comment above. Outputs the byte and a done
// signal when a complete byte has been received.
module TopModule(input clk, input in, input reset, output reg [7:0] out_byte, output reg done);
  reg [2:0] state;
  reg [7:0] data;
  reg [2:0] bit_count;
  always @(posedge clk) begin
    if (reset) begin
      state <= 3'b000;
      data <= 8'b0;
      bit_count <= 3'b000;
      done <= 1'b0;
      out_byte <= 8'b0;
    end else begin
      case (state)
        3'b000: begin // Wait for start bit
          if (in == 1'b0) begin
            state <= 3'b001;
            bit_count <= 3'b001;
          end
        end
        3'b001: begin // Read data bits
          data <= {in, data[7:1]};
          bit_count <= bit_count + 1'b1;
          if (bit_count == 3'b111) state <= 3'b010;
        end
        3'b010: begin // Wait for stop bit
          if (in == 1'b1) begin
            out_byte <= data;
            done <= 1'b1;
          end
          state <= 3'b000;
        end
      endcase
    end
  end
endmodule

