// Finite state machine to correctly receive 8-bit data bytes serialized on
// a single line, with a start bit, 8 data bits, and a stop bit. See the
// comment above the module for details on how the protocol works.
module TopModule (
    input clk,
    input in,
    input reset,
    output reg [7:0] out_byte,
    output reg done
);
    reg [2:0] state;
    reg [7:0] shift_reg;
    reg [2:0] bit_count;
    wire next_state;
    wire shift_in;
    wire done_int;
    wire stop_bit;
    wire start_bit;
    wire [7:0] data_bits;
    wire [7:0] data_bits_swapped;

    always @(posedge clk) begin
        if (reset) begin
            state <= 3'b000;
            shift_reg <= 8'b0;
            bit_count <= 3'b000;
            done <= 1'b0;
        end else begin
            state <= next_state;
            shift_reg <= {shift_in, shift_reg[7:1]};
            bit_count <= bit_count + 1;
            done <= done_int;
        end
    end

    assign start_bit = (state == 3'b000 && in == 1'b0);
    assign stop_bit = (state == 3'b011 && in == 1'b1);
    assign next_state = (state == 3'b000 && start_bit) ? 3'b001
               : (state == 3'b001 && bit_count == 3'b011 && stop_bit) ? 3'b010
               : (state == 3'b010) ? 3'b011
               : (state == 3'b011 && stop_bit) ? 3'b000
               : state;
    assign shift_in = (state == 3'b001) ? in : 1'b0;
    assign done_int = (state == 3'b010) ? 1'b1 : 1'b0;
    assign data_bits = {shift_reg[0], shift_reg[1], shift_reg[2], shift_reg[3], shift_reg[4], shift_reg[5], shift_reg[6], shift_reg[7]};
    assign data_bits_swapped = {data_bits[0], data_bits[1], data_bits[2], data_bits[3], data_bits[4], data_bits[5], data_bits[6], data_bits[7]};
    always @(*) out_byte = data_bits_swapped;
endmodule

