// One-bit FSM for a serial protocol with start/stop bits. Outputs the
// correctly-received byte (out_byte) and a separate "done" signal that
// goes high each time the FSM finds a stop bit.
module TopModule (
    input  clk,
    input  in,
    input  reset,
    output reg [7:0] out_byte,
    output reg done
);
    reg [3:0] bit_count;
    reg [7:0] shift_reg;
    reg start_seen;
    reg stop_seen;
    reg [1:0] idle_count;
    always @(posedge clk) begin
        if (reset) begin
            bit_count <= 4'd0;
            shift_reg <= 8'd0;
            start_seen <= 1'b0;
            stop_seen <= 1'b0;
            idle_count <= 2'd0;
            out_byte <= 8'd0;
            done <= 1'b0;
        end else begin
            if (idle_count == 2'd3) begin
                idle_count <= 2'd0;
            end else begin
                idle_count <= idle_count + 1;
            end
            if (in) begin
                idle_count <= 2'd0;
                if (bit_count == 4'd0) begin
                    start_seen <= 1'b1;
                    bit_count <= bit_count + 1;
                end else if (bit_count < 4'd9) begin
                    shift_reg <= {in, shift_reg[7:1]};
                    bit_count <= bit_count + 1;
                end else if (bit_count == 4'd9) begin
                    stop_seen <= in;
                    if (in) begin
                        out_byte <= shift_reg;
                        done <= 1'b1;
                    end
                    bit_count <= bit_count + 1;
                end else begin
                    bit_count <= 4'd0;
                    shift_reg <= 8'd0;
                    start_seen <= 1'b0;
                    stop_seen <= 1'b0;
                end
            end else if (start_seen) begin
                start_seen <= 1'b0;
                bit_count <= 4'd1;
            end
        end
    end
endmodule

