// Finite state machine to detect start-bit, 8 data bits, and stop-bit
// sequence. If the stop bit is missing, the FSM waits until it is present
// before attempting to receive the next byte. The data byte is valid when
// done is high.
module TopModule(input clk, input in, input reset, output reg [7:0] out_byte, output reg done);
  reg [2:0] state;
  reg [7:0] data;
  reg [2:0] bit_count;
  always @(posedge clk) begin
    if (reset) begin
      state <= 0;
      data <= 8'h00;
      bit_count <= 0;
      out_byte <= 8'h00;
      done <= 0;
    end else begin
      case (state)
        0: begin // Idle state, wait for start bit
          if (in == 1'b0) begin
            state <= 1;
            bit_count <= 0;
          end
        end
        1: begin // Wait for 8 data bits
          if (bit_count == 8) begin
            state <= 2;
          end else begin
            data <= {in, data[7:1]};
            bit_count <= bit_count + 1;
          end
        end
        2: begin // Wait for stop bit
          if (in == 1'b1) begin
            state <= 0;
            out_byte <= data;
            done <= 1;
          end
        end
      endcase
    end
  end
endmodule

