// Finite-state machine to receive a byte (start bit + 8 data bits + stop
// bit) on a serial line, and output the byte when the stop bit is
// received. Active-high synchronous reset.
module TopModule(
    input  clk,
    input  in,
    input  reset,
    output [7:0] out_byte,
    output done
);
    reg [31:0] shift_reg;
    reg [2:0] state;
    reg [7:0] byte;
    reg done_reg;
    wire start = (state == 0) & ~in;
    wire [2:0] next_state = state + 1;
    wire [7:0] next_byte = {in, byte[7:1]};
    always @(*) begin
        if (start) next_state = 1;
    end
    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 0;
            state <= 0;
            byte <= 0;
            done_reg <= 0;
        end else begin
            shift_reg <= {in, shift_reg[31:1]};
            state <= next_state;
            byte <= next_byte;
            done_reg <= (state == 3) & in;
        end
    end
    assign out_byte = byte;
    assign done = done_reg;
endmodule

