// One-shot to generate the start-of-frame pulse.
reg s_start_of_frame;
always @(posedge clk) begin
    if (reset) s_start_of_frame <= 1'b0;
    else       s_start_of_frame <= 1'b0;
    if (in == 1'b0) s_start_of_frame <= 1'b1;
end

// Registers to hold the entire received byte.
reg [7:0] s_byte;
reg [2:0] s_bit_counter;
reg       s_stop_bit;

// Finite state machine to decode the bit stream.
reg [1:0] s_state;
always @(posedge clk) begin
    if (reset) begin
        s_byte <= 8'd0;
        s_bit_counter <= 3'd0;
        s_stop_bit <= 1'b0;
        s_state <= 2'd0;
    end else begin
        case (s_state)
            2'd0: begin // Waiting for the start bit.
                if (in == 1'b0) begin
                    s_state <= 2'd1;
                    s_bit_counter <= 3'd0;
                end
            end
            2'd1: begin // Reading bits 0-7.
                s_byte <= {in, s_byte[7:1]};
                s_bit_counter <= s_bit_counter + 3'd1;
                if (s_bit_counter == 3'd7) s_state <= 2'd2;
            end
            2'd2: begin // Waiting for the stop bit.
                s_stop_bit <= in;
                if (in == 1'b1) s_state <= 2'd0;
            end
        endcase
    end
end

// Output the byte and done signal.
reg done_reg;
always @(posedge clk) begin
    if (reset) done_reg <= 1'b0;
    else       done_reg <= (s_state == 2'd0 && s_start_of_frame);
end
assign done = done_reg;
assign out_byte = s_byte;

